			&ScriptGridExtraToolbarTaxInit;&f;&ScriptTaxClose;
			/* <flatten type="Javascript"> */
function setDefault$Voucher$Tax(f) {
	var g = f.getItem("d71")._controlBehavior, z = f.getItem("r30")._controlBehavior, row = 1;
	if (z._rowCount > 1) {
		setDefaultTaxItems(z, z._activeRow > 0 ? z._activeRow : z._rowCount, ['ma_tc', 'ma_thue', 'thue_suat', 'tk_thue_no', 'tk_cn', 'ma_mau_ct'], [z._taxProperty, z._taxCode, z._taxRate, z._taxAccount, z._taxType, z._voucherTemplate]);
		return;
	}
	if ((z._rowCount > 0) && (z._getItemValue(row, z._getColumnOrder('so_ct0')) == '')) {
		setDefaultTaxItems(z, row, ['mau_bc', 'ma_tc', 'ma_thue', 'thue_suat', 'tk_thue_no', 'tk_cn', 'ma_mau_ct'],
			['3', z._taxProperty, z._taxCode, z._taxRate, z._taxAccount, z._taxType, z._voucherTemplate]);
		setDefaultTaxItems(z, row, ['so_ct0', 'so_seri0', 'ngay_ct0', 't_tien_nt', 't_tien', 'ma_kh', 'ten_kh', 'dia_chi', 'ma_so_thue'], f,
			['so_ct0', 'so_seri0', 'ngay_ct0', 't_tien_nt0', 't_tien0', 'ma_kh', 'ten_ncc', 'dia_chi', 'ma_so_thue']);
		z.assignExpression(row - 1, z.$a.z_t_thue);
		z.assignExpression(row - 1, z.$a.z_t_thue_nt);
		z.validExpression(null, null, [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
		var max = g.max('tien0') + 1;
		if (max > 0) z._getItem(1, z._getColumnOrder('ten_vt')).value = g._getItem(max, g._getColumnOrder('ten_vt%l')).value;
	}
}

function genTaxGrid(f, g, z){
	for (var i = z._rowCount; i >= 1; i--) {
		z._setActiveCell(z._getItem(i, 1))
		z._deleteRow();
	}

	if (g._rowCount > 0) {
		for(var i = 1; i <= g._rowCount; i++){
			z._appendRow(null,true);
			z._setActiveCell(z._getItem(i, 1));
			setDefault$Voucher$TaxAll(f, i);
		}
	}
}
function setDefault$Voucher$TaxAll(f, row) {
	var g = f.getItem("d71")._controlBehavior, z = f.getItem("r30")._controlBehavior;
	var tien = g._getItemValue(row, g._getColumnOrder('tien0')), tien_nt = g._getItemValue(row, g._getColumnOrder('tien_nt0'));

	setDefaultTaxItems(z, z._rowCount, ['mau_bc', 'ma_tc', 'ma_thue', 'thue_suat', 'tk_thue_no', 'tk_cn', 'ma_mau_ct', 't_tien_nt', 't_tien'
		, 'so_ct0', 'so_seri0', 'ngay_ct0', 'ten_vt', 'gc_td1', 'so_luong'],
		['3', z._taxProperty, z._taxCode, z._taxRate, z._taxAccount, z._taxType, g._getItemValue(row, g._getColumnOrder('ma_mau_ct')), tien_nt, tien
			, g._getItemValue(row, g._getColumnOrder('so_ct0')), g._getItemValue(row, g._getColumnOrder('so_seri0')), g._getItemValue(row, g._getColumnOrder('ngay_ct0'))
				, g._getItemValue(row, g._getColumnOrder('ten_vt%l')), g._getItemValue(row, g._getColumnOrder('dvt')), g._getItemValue(row, g._getColumnOrder('so_luong'))]);
	setDefaultTaxItems(z, z._rowCount, ['ma_kh', 'ten_kh', 'dia_chi', 'ma_so_thue'], f,
			['ma_kh', 'ten_ncc', 'dia_chi', 'ma_so_thue']);

	z.assignExpression(row - 1, z.$a.z_t_thue);
	z.assignExpression(row - 1, z.$a.z_t_thue_nt);
	z.validExpression(null, null, [z.$a.t_thue_nt, z.$a.t_thue], [z.$a.t_tt_nt, z.$a.t_tt]);
}
